import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [books, setBooks] = useState([]);
  const [users, setUsers] = useState([]);
  const [issues, setIssues] = useState([]);
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('');

  const API_URL = 'http://localhost:3000/api';

  const showMessage = (msg, type) => {
    setMessage(msg);
    setMessageType(type);
    setTimeout(() => setMessage(''), 3000);
  };

  const loadBooks = async () => {
    try {
      const res = await fetch(`${API_URL}/books`);
      const data = await res.json();
      setBooks(data.books || []);
    } catch (error) {
      showMessage('Error loading books', 'error');
    }
  };

  const loadUsers = async () => {
    try {
      const res = await fetch(`${API_URL}/users`);
      const data = await res.json();
      setUsers(data.users || []);
    } catch (error) {
      showMessage('Error loading users', 'error');
    }
  };

  const loadIssues = async () => {
    try {
      const res = await fetch(`${API_URL}/issues`);
      const data = await res.json();
      setIssues(data.issues || []);
    } catch (error) {
      showMessage('Error loading issues', 'error');
    }
  };

  useEffect(() => {
    loadBooks();
    loadUsers();
    loadIssues();
  }, []);

  const handleAddBook = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          category_id: parseInt(formData.get('category_id')),
          isbn: formData.get('isbn'),
          title: formData.get('title'),
          author: formData.get('author'),
          publisher: formData.get('publisher'),
          publication_year: parseInt(formData.get('publication_year'))
        })
      });

      if (res.ok) {
        showMessage('Book added successfully!', 'success');
        e.target.reset();
        loadBooks();
      } else {
        showMessage('Error adding book', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const handleCheckout = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/issues`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_id: parseInt(formData.get('user_id')),
          book_id: parseInt(formData.get('book_id')),
          due_days: parseInt(formData.get('due_days'))
        })
      });

      if (res.ok) {
        showMessage('Book checked out successfully!', 'success');
        e.target.reset();
        loadBooks();
        loadIssues();
      } else {
        showMessage('Error checking out', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const handleReturn = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/returns`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          issue_id: parseInt(formData.get('issue_id')),
          returned_by_user_id: parseInt(formData.get('returned_by_user_id')),
          condition_notes: formData.get('condition_notes')
        })
      });

      if (res.ok) {
        showMessage('Book returned successfully!', 'success');
        e.target.reset();
        loadBooks();
        loadIssues();
      } else {
        showMessage('Error returning', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const handleReserve = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/reservations`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_id: parseInt(formData.get('user_id')),
          book_id: parseInt(formData.get('book_id')),
          expire_days: parseInt(formData.get('expire_days'))
        })
      });

      if (res.ok) {
        showMessage('Book reserved successfully!', 'success');
        e.target.reset();
      } else {
        showMessage('Error reserving', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const availableBooks = books.filter(b => b.status === 'available');
  const issuedBooks = books.filter(b => b.status === 'issued');
  const activeIssues = issues.filter(i => i.status !== 'completed');

  return (
    <div className="app">
      <nav className="navbar">
        <div className="navbar-container">
          <h1 className="logo">📚 LibraryHub</h1>
          <div className="nav-buttons">
            <button 
              className={`nav-btn ${activeTab === 'dashboard' ? 'active' : ''}`}
              onClick={() => setActiveTab('dashboard')}
            >
              Dashboard
            </button>
            <button 
              className={`nav-btn ${activeTab === 'books' ? 'active' : ''}`}
              onClick={() => setActiveTab('books')}
            >
              Books
            </button>
            <button 
              className={`nav-btn ${activeTab === 'checkout' ? 'active' : ''}`}
              onClick={() => setActiveTab('checkout')}
            >
              Checkout
            </button>
            <button 
              className={`nav-btn ${activeTab === 'return' ? 'active' : ''}`}
              onClick={() => setActiveTab('return')}
            >
              Return
            </button>
            <button 
              className={`nav-btn ${activeTab === 'reserve' ? 'active' : ''}`}
              onClick={() => setActiveTab('reserve')}
            >
              Reserve
            </button>
            <button 
              className={`nav-btn ${activeTab === 'admin' ? 'active' : ''}`}
              onClick={() => setActiveTab('admin')}
            >
              Admin
            </button>
          </div>
        </div>
      </nav>

      <main className="main-container">
        {message && <div className={`alert ${messageType}`}>{message}</div>}

        {/* Dashboard */}
        {activeTab === 'dashboard' && (
          <div className="section">
            <div className="dashboard-header">
              <h2>Welcome to LibraryHub</h2>
              <p>Your modern library management system</p>
            </div>

            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-icon">📚</div>
                <h3>{books.length}</h3>
                <p>Total Books</p>
              </div>
              <div className="stat-card">
                <div className="stat-icon">👥</div>
                <h3>{users.length}</h3>
                <p>Users</p>
              </div>
              <div className="stat-card">
                <div className="stat-icon">✅</div>
                <h3>{availableBooks.length}</h3>
                <p>Available Books</p>
              </div>
              <div className="stat-card">
                <div className="stat-icon">📤</div>
                <h3>{issuedBooks.length}</h3>
                <p>Issued Books</p>
              </div>
              <div className="stat-card">
                <div className="stat-icon">📋</div>
                <h3>{activeIssues.length}</h3>
                <p>Active Issues</p>
              </div>
            </div>

            <div className="recent-section">
              <h3>Recent Books Added</h3>
              <div className="book-preview-grid">
                {books.slice(0, 4).map(book => (
                  <div key={book.book_id} className="book-preview-card">
                    <div className="book-icon">📖</div>
                    <h4>{book.title}</h4>
                    <p>{book.author}</p>
                    <span className={`badge ${book.status}`}>{book.status}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Books Catalog */}
        {activeTab === 'books' && (
          <div className="section">
            <div className="section-header">
              <h2>📖 Books Catalog</h2>
              <div className="filter-buttons">
                <button className="filter-btn active">All</button>
                <button className="filter-btn">Available</button>
                <button className="filter-btn">Issued</button>
              </div>
            </div>

            <div className="books-grid">
              {books.map(book => (
                <div key={book.book_id} className="book-card">
                  <div className="book-cover">📖</div>
                  <div className="book-info">
                    <h3>{book.title}</h3>
                    <p className="author">{book.author}</p>
                    <p className="isbn">ISBN: {book.isbn}</p>
                    {book.publisher && <p className="publisher">{book.publisher}</p>}
                    <div className="book-footer">
                      <span className={`status-badge ${book.status}`}>{book.status}</span>
                      <span className="book-id">#{book.book_id}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Checkout */}
        {activeTab === 'checkout' && (
          <div className="section">
            <div className="section-header">
              <h2>📤 Checkout Book</h2>
            </div>

            <div className="form-container">
              <form onSubmit={handleCheckout} className="modern-form">
                <div className="form-group">
                  <label>Select User</label>
                  <select name="user_id" required>
                    <option value="">-- Choose a user --</option>
                    {users.map(u => (
                      <option key={u.user_id} value={u.user_id}>
                        {u.full_name} ({u.role})
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Select Book</label>
                  <select name="book_id" required>
                    <option value="">-- Choose a book --</option>
                    {books.filter(b => b.status === 'available').map(b => (
                      <option key={b.book_id} value={b.book_id}>
                        {b.title} by {b.author}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Due Days</label>
                  <input type="number" name="due_days" defaultValue="14" required />
                </div>

                <button type="submit" className="btn-primary">Checkout Book</button>
              </form>
            </div>
          </div>
        )}

        {/* Return */}
        {activeTab === 'return' && (
          <div className="section">
            <div className="section-header">
              <h2>📥 Return Book</h2>
            </div>

            <div className="form-container">
              <form onSubmit={handleReturn} className="modern-form">
                <div className="form-group">
                  <label>Select Issue</label>
                  <select name="issue_id" required>
                    <option value="">-- Choose an issue --</option>
                    {issues.filter(i => i.status !== 'completed').map(i => (
                      <option key={i.issue_id} value={i.issue_id}>
                        Issue #{i.issue_id} - Book #{i.book_id}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Returned By (Librarian)</label>
                  <select name="returned_by_user_id" required>
                    <option value="">-- Choose a librarian --</option>
                    {users.filter(u => u.role === 'librarian').map(u => (
                      <option key={u.user_id} value={u.user_id}>{u.full_name}</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Condition Notes</label>
                  <textarea name="condition_notes" placeholder="Enter book condition..."></textarea>
                </div>

                <button type="submit" className="btn-primary">Process Return</button>
              </form>
            </div>
          </div>
        )}

        {/* Reserve */}
        {activeTab === 'reserve' && (
          <div className="section">
            <div className="section-header">
              <h2>🔖 Reserve Book</h2>
            </div>

            <div className="form-container">
              <form onSubmit={handleReserve} className="modern-form">
                <div className="form-group">
                  <label>Select User</label>
                  <select name="user_id" required>
                    <option value="">-- Choose a user --</option>
                    {users.map(u => (
                      <option key={u.user_id} value={u.user_id}>{u.full_name}</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Select Book</label>
                  <select name="book_id" required>
                    <option value="">-- Choose a book --</option>
                    {books.map(b => (
                      <option key={b.book_id} value={b.book_id}>{b.title}</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Expire Days</label>
                  <input type="number" name="expire_days" defaultValue="7" required />
                </div>

                <button type="submit" className="btn-primary">Reserve Book</button>
              </form>
            </div>
          </div>
        )}

        {/* Admin - Add Books */}
        {activeTab === 'admin' && (
          <div className="section">
            <div className="section-header">
              <h2>⚙️ Admin Panel</h2>
            </div>

            <div className="admin-container">
              <div className="admin-card">
                <h3>Add New Book</h3>
                <form onSubmit={handleAddBook} className="modern-form">
                  <div className="form-row">
                    <div className="form-group">
                      <label>Title *</label>
                      <input type="text" name="title" required />
                    </div>
                    <div className="form-group">
                      <label>Author *</label>
                      <input type="text" name="author" required />
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>ISBN *</label>
                      <input type="text" name="isbn" required />
                    </div>
                    <div className="form-group">
                      <label>Publisher</label>
                      <input type="text" name="publisher" />
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>Category ID *</label>
                      <input type="number" name="category_id" defaultValue="1" required />
                    </div>
                    <div className="form-group">
                      <label>Publication Year</label>
                      <input type="number" name="publication_year" />
                    </div>
                  </div>

                  <button type="submit" className="btn-primary">Add Book</button>
                </form>
              </div>

              <div className="admin-card info-card">
                <h3>Category IDs</h3>
                <ul>
                  <li>1 = Fiction</li>
                  <li>2 = Science</li>
                  <li>3 = History</li>
                  <li>4 = Technology</li>
                  <li>5 = Biography</li>
                </ul>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
